insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목회자가 ''같은 집을 자주 심방하는 것을 피해야 하는'' 주된 이유는?', '["불필요한 오해와 구설수를 방지하기 위함", "특정 교인에게만 편중된 심방을 피하기 위함", "심방 시간을 효율적으로 사용하기 위함", "개인적인 친분을 쌓는 것을 피하기 위함"]'::jsonb, 0);
