insert into public.exam_questions (subject, question, options, answer) values ('목회학', '예배 시간에 ''특정한 여자 성도만 치중하여 보지 말아야'' 하는 이유는?', '["성도들 간의 불필요한 비교를 막기 위함", "설교에 집중하기 위함", "목회자의 공정성과 청렴성을 유지하고 오해를 방지하기 위함", "모든 성도를 균등하게 대하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '다음 중 목사가 하나님의 사람으로 쓰임 받는 데 가장 큰 방해가 되는 것은?', '["설교 준비에 시간을 많이 할애하는 것", "목사직을 직업으로 생각하는 것", "교인들의 의견을 경청하는 것", "꾸준히 자기 수양에 힘쓰는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''남을 가르치는 것에 전력하느라 자기 수양을 못하는 것''이 목회에 미치는 부정적인 영향은?', '["목회자 자신의 영적, 인격적 성장이 정체되어 사역의 깊이가 얕아질 수 있다.", "교인들이 목회자의 설교에 집중하지 않는다.", "교회의 재정 수입이 줄어든다.", "목회자의 사회적 관계가 단절된다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''자기가 특별한 사람인 줄로 생각하는 것''이 목회에 미치는 해로운 영향은?', '["목회자가 주변의 비판에 더욱 민감해진다.", "목회자가 더 많은 권한을 행사할 수 있게 한다.", "목회자의 교만으로 이어져 동역자 및 교인들과의 관계를 해치고 사역을 그르칠 수 있다.", "교인들이 목회자에게 더 많은 존경을 표한다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''영혼을 위해 근심하고 힘쓰지 않는 것''이 목회에 미치는 가장 심각한 결과는?', '["목회자의 개인적인 만족감이 낮아진다.", "목회의 본질적인 목적을 상실하고 영적인 돌봄이 부재하게 된다.", "교인의 수가 줄어든다.", "교회 예산이 부족해진다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '심방의 주된 목적 중 하나는?', '["목회자의 개인적인 휴식을 위함", "성도의 형편과 신앙생활을 파악하고 영적인 돌봄을 제공하기 위함", "단순히 교인들과 사교 활동을 하기 위함", "교인들의 재정 상태를 파악하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '심방을 통해 ''성도들의 불평거리를 해소할 수 있는'' 이유는?', '["불평하는 교인들을 질책하기 위함", "목회자가 모든 문제를 해결해 주기 때문", "불평을 직접 듣고 기록하기 위함", "직접적인 소통을 통해 오해를 풀고 위로와 공감을 제공할 수 있기 때문"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '심방을 통해 목회자가 얻을 수 있는 유익 중 ''설교할 자료''를 얻는다는 것은 어떤 의미입니까?', '["설교 준비 시간을 단축하기 위함", "교인들의 사적인 이야기를 설교에 그대로 사용하는 것", "설교 내용을 즉흥적으로 바꾸기 위함", "교인들의 실제 삶과 고민을 이해하여 설교에 현실적인 적용과 깊이를 더하는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '심방이 목회 사역에서 중요한 이유 중 하나로, ''믿음이 없거나 열심이 없는 사람과 교제할 기회''가 된다는 것은 무엇을 의미합니까?', '["그들을 강제로 교회에 나오게 할 수 있다.", "단순히 그들의 생활 습관을 파악하는 것이다.", "개인적인 관계를 통해 복음을 전하고 영적인 영향력을 미칠 수 있는 통로가 된다.", "그들의 신앙을 억지로 변화시키려 하는 것이다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '심방할 때 ''지나치게 엄숙하지 말라''고 하는 이유는?', '["교인들에게 편안함과 친밀감을 주어 마음을 열게 하기 위함이다.", "심방 내용을 중요하게 생각하지 말라는 의미이다.", "심방 시간을 가볍게 여기라는 의미이다.", "목회자의 권위를 낮추기 위함이다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '심방 시 ''가정의 형편을 따라 융통성 있게 하라''는 조언의 의미는?', '["각 가정의 상황과 필요에 맞게 심방 방식과 내용을 조절해야 한다는 의미이다.", "심방 일정을 마음대로 변경해도 된다는 의미이다.", "목회자가 모든 가정의 형편을 완벽하게 파악해야 한다는 의미이다.", "융통성이 없으면 심방을 하지 말라는 의미이다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '심방 시 ''심방받는 가족 모두와 접촉하도록 힘쓰라''는 지침의 중요성은?', '["모든 가족 구성원의 개인 정보를 수집하기 위함", "가족 구성원 모두에게 영적인 돌봄과 관계를 확장하기 위함", "심방 시간을 길게 늘리기 위함", "가족 구성원 간의 갈등을 유발하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목회 상담의 세 가지 특성 중 ''영적 특성''과 가장 관련 깊은 것은?', '["내담자의 감정 이해", "말씀에 친숙함", "상담자의 자기 이해", "풍부한 경험"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''인격적 특성''이 목회 상담에서 요구하는 것은?', '["내담자에게 심리적 조언을 강요하는 것", "내담자를 이해하고 수용할 수 있는 풍부한 경험", "내담자의 지식을 평가하는 능력", "상담자가 심리학 전문가여야 한다는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목회 상담의 ''영적 특성''이 강조하는 ''하나님을 두려워함''의 의미는?', '["하나님을 무서워하고 피하는 것", "하나님께 상담의 모든 책임을 전가하는 것", "하나님 앞에서 겸손하고 경외하는 마음으로 상담에 임하는 것", "상담 내용을 외부에 발설하지 않는 것"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목사의 가정생활이 ''이웃에게 영향을 끼쳐야 하는'' 주된 이유는?', '["가정을 완벽하게 보이기 위함", "개인적인 명성을 얻기 위함", "교회의 덕을 세우고 그리스도의 모습을 드러내기 위함", "사회적으로 인정받기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''부부가 좋은 동역자가 되어야 하는'' 이유로 가장 적절한 것은?', '["교인들에게 이상적인 부부상을 보여주기 위함", "서로를 이해하고 지지하며 목회 사역을 함께 감당하는 데 힘이 되기 위함", "부부 싸움을 피하기 위함", "목회 사역의 모든 업무를 분담하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목회자가 ''강단에서 하는 설교를 가정에서 실천해야 하는'' 주된 이유는?', '["설교 준비 시간을 단축하기 위함", "목회자의 언행일치를 통해 진정성을 보이고 가정이 신앙의 본보기가 되기 위함", "가족 구성원들에게 신앙을 강요하기 위함", "가정 내의 질서를 확립하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '다음 중 목사의 행복한 가정생활이 목회에 미치는 긍정적인 영향은?', '["목회 사역에 큰 힘과 안정감을 제공하며, 교인들에게도 좋은 영향을 미친다.", "교인들의 헌금이 늘어난다.", "교회의 규모가 자동으로 커진다.", "목회자가 개인적인 시간을 더 많이 가질 수 있다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '축도(축복기도)의 성경적 근거를 제시하는 대표적인 구절은?', '["요한복음 3:16", "마태복음 28:19", "사도행전 1:8", "고린도후서 13:13"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '고린도후서 13:13 에 나타난 축도의 세 가지 핵심 요소는?', '["예수 그리스도의 은혜, 하나님의 사랑, 성령의 교통하심", "믿음, 소망, 사랑", "구원, 축복, 영생", "말씀, 성례, 기도"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '유아세례를 베풀기 위해 필요한 부모의 조건은?', '["부모 모두가 신자여야 한다.", "부모 둘 중 한 사람 이상이 신자여야 한다.", "부모가 교회 봉사자여야 한다.", "부모가 재정적으로 헌신적이어야 한다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '유아세례 시 문답과 서약을 받는 대상은?', '["목사와 장로", "유아의 부모", "유아세례를 참관하는 교인들", "유아 본인"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '유아세례를 받은 자녀가 ''만 15 세가 되면 입교 문답을 하여 입교 교인이 된다''는 것의 의미는?', '["교회 직분자가 될 수 있다.", "자신의 신앙을 고백하고 교회의 정식 회원으로 인정받는 절차이다.", "유아세례가 취소되고 새로운 세례를 받는다.", "교회의 모든 의무에서 면제된다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '학습을 받기 위한 신앙생활 기간 기준은?', '["3 개월 이상", "6 개월 이상", "1 년 이상", "2 년 이상"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '학습 문답을 받을 수 있는 최소 연령은?', '["만 10 세 이상", "만 12 세 이상", "만 14 세 이상", "만 16 세 이상"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '세례를 받기 위한 조건 중 하나는?', '["학습을 받은 지 6 개월 이상이 되어야 한다.", "교회 재정에 크게 기여해야 한다.", "교회의 모든 행사에 참여해야 한다.", "교회의 특정 직분을 맡아야 한다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '세례 문답과 서약을 하는 주체는?', '["당회원 전체", "세례를 받으려는 사람", "담임 목사", "학습을 받은 교인"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '교회 재정 처리에 대한 지도 원칙으로 옳지 않은 것은?', '["제직회가 금전 처리에 간섭해야 한다.", "금전 처리는 개인에게 전적으로 맡겨야 한다.", "회계는 영수증을 사용해야 한다.", "정기 공동의회에서 회계 감사를 받아야 한다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '교회 재정 관리에서 ''교회의 공금과 개인의 돈을 함께 섞어 두지 말게 해야 하는'' 이유는?', '["재정 운영의 효율성을 높이기 위함", "개인의 편의를 제공하기 위함", "재정의 투명성과 청렴성을 유지하고 오해를 방지하기 위함", "개인의 재산 증식을 돕기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '교회 재정으로 ''지나치게 큰 사업은 삼가야 하며, 이미 시작한 사업은 등한히 하면서 새 사업에 열중하는 폐단을 없애야 하는'' 이유는?', '["모든 사업 계획을 포기하기 위함", "재정 담당자의 업무 부담을 줄이기 위함", "재정의 건전성을 유지하고 무분별한 지출을 막기 위함", "교회의 규모를 축소하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목사 본인의 사례비에 대하여 ''관여하지 않는 것이 바람직하다''고 하는 이유는?', '["교회의 재정 상황을 목사에게 알리지 않기 위함", "목사의 권위를 유지하기 위함", "재정 운영의 투명성과 공정성을 확보하고 불필요한 논란을 피하기 위함", "목사의 개인적인 재정 관리를 존중하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목사가 반대에 부딪혔을 때 가장 먼저 해야 할 일은?', '["즉시 반대자를 찾아가 설득하는 것", "먼저 은밀하게 기도하고 자기 자신을 살펴보며 반성하는 것", "교인들에게 자신의 입장을 강하게 피력하는 것", "당회에 보고하여 반대자를 징계 요청하는 것"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '잘못된 사건으로 반대에 부딪혔을 때 목사의 바람직한 태도는?', '["끝까지 자신의 주장을 고수하는 것", "상황을 모면하기 위해 거짓말하는 것", "반대자들에게 책임을 전가하는 것", "공석이든 사석이든 잘못을 인정하는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '반대에 대해 ''사랑의 권면으로 부드럽게 대해야 하는'' 이유는?', '["목회자의 약한 모습을 보이지 않기 위함", "논쟁을 피하기 위함", "상대방의 감정을 자극하지 않기 위함", "관계의 회복과 궁극적인 유익을 도모하기 위함"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목사가 반대에 직면했을 때 ''무엇보다 먼저 교회의 유익을 우선으로 삼아야 하는'' 이유는?', '["교회의 본질적인 사명과 공동체의 덕을 세우는 것이 최우선이기 때문", "목회자의 리더십을 강화하기 위함", "개인적인 감정을 배제하기 위함", "불필요한 분쟁을 막기 위함"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '대체로 성경의 교훈에 따라 술을 금지하는 주된 이유는?', '["성경은 술에 취하는 것과 성령에 충만한 것을 대조하는데, 이는 무엇이 나를 지배하는지에 대한 문제이기 때문", "재정적 낭비를 막기 위함", "건강에 해롭기 때문", "사회적 지위를 유지하기 위함"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''무엇을 먹든지 마시든지 하나님의 영광을 위해 해야 한다''는 원칙이 음주 흡연과 관련하여 의미하는 바는?', '["자신의 기호대로 자유롭게 행동해도 된다는 것", "아무것도 먹거나 마시지 말아야 한다는 것", "모든 행위가 하나님의 뜻에 합당하고 덕을 세우는 방향으로 이루어져야 한다는 것", "육체적인 쾌락을 추구해야 한다는 것"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''우리 몸은 하나님의 성전이요, 주님의 몸의 지체이므로 몸에 해로운 것은 삼가야 한다''는 가르침은 음주 흡연에 대해 무엇을 시사합니까?', '["영적인 건강만 중요하고 육체적인 건강은 중요하지 않다는 것이다.", "몸에 해로운 음식은 먹지 말아야 한다.", "운동을 열심히 해야 한다.", "음주와 흡연이 몸에 해로움을 인정하고 이를 멀리해야 한다는 교훈이다."]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '다음 중 음주와 흡연에 대한 성경적 관점과 가장 거리가 먼 것은?', '["경건한 생활과 배치될 수 있다.", "문제의 원인이 될 수 있다.", "개인의 자유에 속하므로 아무런 제약이 없다.", "몸을 더럽히는 행위로 간주될 수 있다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '에베소서 4:11-12 에 근거하여 목사의 직무에 해당하지 않는 것은?', '["교회 재정을 증식하는 것", "성도를 온전하게 하는 것", "그리스도의 몸을 세우는 것", "봉사의 일을 하게 하는 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목사의 직무 중 ''성도를 온전하게 하는 것''의 의미는?', '["성도들의 학력을 높이는 것", "성도를 육체적으로 완벽하게 만드는 것", "성도를 재정적으로 풍요롭게 하는 것", "성도들이 그리스도 안에서 영적으로 성숙하고 봉사에 합당하게 준비되도록 돕는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''봉사의 일을 하게 하는 것''이 목사의 직무인 이유는?', '["교인들에게 의무감을 부여하기 위함", "교회의 대외 이미지를 좋게 하기 위함", "목사의 업무 부담을 줄이기 위함", "성도들이 각자의 은사대로 교회를 섬기도록 훈련하고 동기를 부여하기 위함"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''그리스도의 몸을 세우는 것''이라는 목사의 직무에 대한 설명으로 옳은 것은?', '["건물을 건축하여 교회를 물리적으로 확장하는 것", "교회의 명성을 세상에 널리 알리는 것", "다른 교회들을 통합하여 규모를 키우는 것", "교회 공동체가 예수 그리스도를 머리로 하여 영적으로 성장하고 굳건해지도록 하는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '다음 중 목사가 각별히 주의해야 할 가장 위험한 것은?', '["과식", "명예욕", "게으름", "독서 부족"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''명예를 탐내지 말 것''이라고 하는 주된 이유는?', '["교만으로 이어져 하나님으로부터 버림받거나 사역에 큰 해를 입을 수 있기 때문", "교인들이 목사를 무시하게 된다.", "목회자의 개인적인 삶이 불행해지기 때문", "명예는 목회와 아무런 관련이 없기 때문"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '목회자가 돈을 탐하는 것이 목회에 치명적인 이유는?', '["교인들의 헌금이 줄어든다.", "''일만 악의 뿌리''인 돈을 사랑하다가 목회에 실패하고 삯꾼 목자가 될 수 있기 때문", "목사의 생활이 궁핍해진다.", "교회가 재정적으로 어려워진다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('목회학', '''이성을 주의할 것''이 목회자에게 각별히 강조되는 이유는?', '["이성과의 교제를 완전히 단절해야 하기 때문", "여자 문제로 패가망신하고 목회를 포기하는 경우가 종종 발생하기 때문", "목회자가 이성적인 판단을 하지 못하게 되기 때문", "교인들이 목사를 질투하게 되기 때문"]'::jsonb, 1);
